g=[[0]*30 for _ in range(30)]
for r in range(1,26):
 for c in range(1,26):
  if r in (1,25) or c in (1,25): g[r][c]=5
for depth in range(1,11):
 color=2 if depth%2 else 5
 lo=1+depth; hi=25-depth
 for c in range(lo,hi+1):
  g[lo][c]=g[hi][c]=color
 for r in range(lo,hi+1):
  g[r][lo]=g[r][hi]=color
print('\n'.join(str(row) for row in g))

